<?php include '../includes/header.php';$u=user();$q=trim($_GET['q']??'');$status=$_GET['status']??'';$like='%'.$q.'%';if(is_admin()){$sql="SELECT r.*,u.name owner_name FROM records r JOIN users u ON u.id=r.owner_id WHERE (r.title LIKE ? OR r.reference_number LIKE ? OR r.institution_code LIKE ?) ".($status?"AND r.status=? ":"")."ORDER BY r.id DESC";$s=mysqli_prepare($conn,$sql);if($status)mysqli_stmt_bind_param($s,'ssss',$like,$like,$like,$status);else mysqli_stmt_bind_param($s,'sss',$like,$like,$like);}else{$sql="SELECT r.*,u.name owner_name FROM records r JOIN users u ON u.id=r.owner_id WHERE r.institution_type=? AND r.institution_code=? AND (r.title LIKE ? OR r.reference_number LIKE ? OR r.institution_name LIKE ?) ".($status?"AND r.status=? ":"")."ORDER BY r.id DESC";$s=mysqli_prepare($conn,$sql);if($status)mysqli_stmt_bind_param($s,'ssssss',$u['institution_type'],$u['institution_code'],$like,$like,$like,$status);else mysqli_stmt_bind_param($s,'sssss',$u['institution_type'],$u['institution_code'],$like,$like,$like);}mysqli_stmt_execute($s);$r=mysqli_stmt_get_result($s);?>
<div class="page-head"><div><p class="eyebrow">RECORDS</p><h1>Institution Records</h1></div><a class="btn primary" href="create.php">+ New Record</a></div>
<div class="card"><form class="filters"><input name="q" value="<?=e($q)?>" placeholder="Search title, reference or institution"><select name="status"><option value="">All status</option><?php foreach(['pending','active','completed','archived'] as $x):?><option <?=$status===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select><button>Filter</button></form></div>
<div class="card table-wrap"><table><tr><th>Reference</th><th>Title</th><th>Category</th><th>Institution</th><th>Status</th><th>Due</th><th>Action</th></tr><?php while($x=mysqli_fetch_assoc($r)):?><tr><td><?=e($x['reference_number'])?></td><td><?=e($x['title'])?></td><td><?=e($x['category'])?></td><td><?=e($x['institution_code'])?></td><td><span class="pill"><?=e($x['status'])?></span></td><td><?=e($x['due_date']?:'—')?></td><td><a href="view.php?id=<?=$x['id']?>">View</a></td></tr><?php endwhile;?></table></div><?php include '../includes/footer.php';?>
